package backup

import (
	"bytes"
	"context"
	"crypto/sha256"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestAuditBackupReadmeCompatibility(t *testing.T) {
	const producerHash = "c1055ca973a7b06da3ebdeece5975dd8ab5eed3e575439f191da5c48e9b222a3"
	if fmt.Sprintf("%x", sha256.Sum256([]byte(legacyBackupReadme))) != producerHash || len(legacyBackupReadme) != 3041 {
		t.Fatal("legacy template differs from producer 0663d388")
	}
	for _, tc := range []struct {
		name       string
		body       string
		failedPush bool
		executable bool
		reject     bool
	}{
		{name: "unpublished-legacy-init", body: legacyBackupReadme},
		{name: "failed-legacy-push", body: legacyBackupReadme, failedPush: true},
		{name: "current", body: backupReadme},
		{name: "edited-legacy", body: strings.Replace(legacyBackupReadme, "# backup-wacrawl", "# edited-backup", 1), reject: true},
		{name: "private-addition", body: legacyBackupReadme + "\nsynthetic private note\n", reject: true},
		{name: "executable-legacy", body: legacyBackupReadme, executable: true, reject: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			parent := t.TempDir()
			remote := filepath.Join(parent, "remote.git")
			initBareRemote(t, remote)
			opts := Options{
				Repo: filepath.Join(parent, "repo"), Remote: remote,
				Identity: filepath.Join(parent, "age.key"), ConfigPath: filepath.Join(parent, "backup.json"),
			}
			runGit(t, parent, "init", "-b", "main", opts.Repo)
			runGit(t, opts.Repo, "remote", "add", "origin", remote)
			readme := filepath.Join(opts.Repo, "README.md")
			if err := os.WriteFile(readme, []byte(tc.body), 0o600); err != nil {
				t.Fatal(err)
			}
			runGit(t, opts.Repo, "add", "README.md")
			if tc.executable {
				runGit(t, opts.Repo, "update-index", "--chmod=+x", "README.md")
			}
			runGit(t, opts.Repo, "commit", "-m", "test: unpublished producer init")
			oldHead := strings.TrimSpace(string(auditGitBytes(t, opts.Repo, "rev-parse", "HEAD")))
			oldCommit := auditGitBytes(t, opts.Repo, "cat-file", "commit", oldHead)
			runGit(t, opts.Repo, "tag", "snapshot/producer-init")
			tags := auditGitBytes(t, opts.Repo, "show-ref", "--tags")
			if tc.reject {
				if err := os.WriteFile(readme, []byte(legacyBackupReadme), 0o600); err != nil {
					t.Fatal(err)
				}
				runGit(t, opts.Repo, "add", "README.md")
				runGit(t, opts.Repo, "commit", "-m", "test: repair only current README")
			}
			if _, _, err := Init(ctx, opts); err != nil {
				t.Fatal(err)
			}
			read := func(dir, name string) []byte {
				t.Helper()
				data, err := fs.ReadFile(os.DirFS(dir), name)
				if err != nil {
					t.Fatal(err)
				}
				return data
			}
			originalReadme := read(opts.Repo, "README.md")
			info, err := os.Stat(readme)
			if err != nil {
				t.Fatal(err)
			}
			identity, config := read(parent, "age.key"), read(parent, "backup.json")
			sentinel := filepath.Join(opts.Repo, "unrelated.txt")
			if err := os.WriteFile(sentinel, []byte("staged sentinel"), 0o600); err != nil {
				t.Fatal(err)
			}
			runGit(t, opts.Repo, "add", "unrelated.txt")
			if err := os.WriteFile(sentinel, []byte("working sentinel"), 0o600); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(opts.Repo, "untracked.txt"), []byte("untracked sentinel"), 0o600); err != nil {
				t.Fatal(err)
			}
			index := auditGitBytes(t, opts.Repo, "diff", "--cached", "--binary")
			st := openFixtureStore(t, "archive.db")
			opts.Push = true
			var pending []byte
			if tc.failedPush {
				hook := filepath.Join(remote, "hooks", "pre-receive")
				if err := os.WriteFile(hook, []byte("#!/bin/sh\nexit 1\n"), 0o700); err != nil { // #nosec G306 -- owner-only executable refusal hook in this test's temp bare remote.
					t.Fatal(err)
				}
				if _, err := Push(ctx, st, opts); err == nil || strings.Contains(err.Error(), "unverified unpublished") {
					t.Fatalf("expected remote refusal after valid history: %v", err)
				}
				pending = auditGitBytes(t, opts.Repo, "rev-parse", "HEAD")
				if err := os.Remove(hook); err != nil {
					t.Fatal(err)
				}
			}
			result, err := Push(ctx, st, opts)
			if tc.reject {
				if err == nil || !strings.Contains(err.Error(), "unverified unpublished") {
					t.Fatalf("accepted unsafe historical README: %v", err)
				}
			} else if err != nil || result.Changed == tc.failedPush {
				t.Fatalf("publish known README: %+v, %v", result, err)
			}
			head := auditGitBytes(t, opts.Repo, "rev-parse", "HEAD")
			if tc.failedPush && !bytes.Equal(head, pending) {
				t.Fatal("retry replaced the refused local snapshot commit")
			}
			retry, err := Push(ctx, st, opts)
			if tc.reject {
				if err == nil || !strings.Contains(err.Error(), "unverified unpublished") {
					t.Fatalf("unchanged retry accepted unsafe history: %v", err)
				}
				if got := auditGitBytes(t, remote, "for-each-ref"); len(got) != 0 {
					t.Fatalf("unsafe history published: %s", got)
				}
			} else {
				if err != nil || retry.Changed {
					t.Fatalf("unchanged retry: %+v, %v", retry, err)
				}
				if !bytes.Equal(head, auditGitBytes(t, remote, "rev-parse", "refs/heads/main")) {
					t.Fatal("remote did not receive the existing snapshot")
				}
			}
			if !bytes.Equal(head, auditGitBytes(t, opts.Repo, "rev-parse", "HEAD")) {
				t.Fatal("unchanged retry created or replaced a commit")
			}
			runGit(t, opts.Repo, "merge-base", "--is-ancestor", oldHead, "HEAD")
			if !bytes.Equal(oldCommit, auditGitBytes(t, opts.Repo, "cat-file", "commit", oldHead)) ||
				!bytes.Equal(tags, auditGitBytes(t, opts.Repo, "show-ref", "--tags")) ||
				string(auditGitBytes(t, opts.Repo, "show", oldHead+":README.md")) != tc.body {
				t.Fatal("producer commit, README or tags changed")
			}
			after, err := os.Stat(readme)
			if err != nil || after.Mode() != info.Mode() || !bytes.Equal(originalReadme, read(opts.Repo, "README.md")) {
				t.Fatalf("working README bytes or mode changed: %v", err)
			}
			if !bytes.Equal(index, auditGitBytes(t, opts.Repo, "diff", "--cached", "--binary")) ||
				string(read(opts.Repo, "unrelated.txt")) != "working sentinel" ||
				string(read(opts.Repo, "untracked.txt")) != "untracked sentinel" {
				t.Fatal("unrelated index or worktree content changed")
			}
			if !bytes.Equal(identity, read(parent, "age.key")) || !bytes.Equal(config, read(parent, "backup.json")) {
				t.Fatal("private identity or configuration changed")
			}
		})
	}
}

package main

import "testing"

func TestRunHelp(t *testing.T) {
	if code := run([]string{"help"}); code != 0 {
		t.Fatalf("run help exit code = %d, want 0", code)
	}
	if code := run([]string{"--version"}); code != 0 {
		t.Fatalf("run version exit code = %d, want 0", code)
	}
	if code := run([]string{"nope"}); code != 2 {
		t.Fatalf("run invalid exit code = %d, want 2", code)
	}
}

package store

import (
	"context"
	"path/filepath"
	"reflect"
	"testing"
	"time"
)

func TestSearchDateFiltersAndOrder(t *testing.T) {
	ctx := context.Background()
	st, err := Open(ctx, filepath.Join(t.TempDir(), "search.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = st.Close() })
	older := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	newer := older.Add(24 * time.Hour)
	for _, row := range []struct {
		pk   int64
		ts   int64
		text string
	}{
		{1, 0, "launch unknown"},
		{2, -1, "launch negative"},
		{3, maxJSONUnixSecond + 1, "launch future"},
		{4, older.Unix(), "launch older with several other words here"},
		{5, newer.Unix(), "launch launch launch launch"},
		{6, newer.Unix(), "launch launch launch"},
	} {
		if _, err := st.DB().ExecContext(ctx, `insert into messages(source_pk,event_id,chat_jid,msg_id,ts,from_me,text,raw_type) values(?,?,'chat',?,?,0,?,0)`, row.pk, messageEventID(row.pk), messageEventID(row.pk), row.ts, row.text); err != nil {
			t.Fatal(err)
		}
		if _, err := st.DB().ExecContext(ctx, `insert into messages_fts(rowid,text) values(?,?)`, row.pk, row.text); err != nil {
			t.Fatal(err)
		}
	}
	for _, tc := range []struct {
		name   string
		filter MessageFilter
		want   []int64
	}{
		{"after excludes unknown dates", MessageFilter{After: &older}, []int64{5, 6, 4}},
		{"before excludes unknown dates", MessageFilter{Before: &newer}, []int64{5, 6, 4}},
		{"range includes endpoints", MessageFilter{After: &older, Before: &newer}, []int64{5, 6, 4}},
		{"ascending overrides relevance", MessageFilter{After: &older, Before: &newer, Asc: true}, []int64{4, 5, 6}},
		{"ascending retains unknown dates first", MessageFilter{Asc: true}, []int64{1, 2, 3, 4, 5, 6}},
		{"ascending limit selects oldest", MessageFilter{After: &older, Asc: true, Limit: 1}, []int64{4}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			filter := tc.filter
			filter.Query = "launch"
			got, err := st.Search(ctx, filter)
			if err != nil {
				t.Fatal(err)
			}
			var pks []int64
			for _, message := range got {
				pks = append(pks, message.SourcePK)
			}
			if !reflect.DeepEqual(pks, tc.want) {
				t.Fatalf("search source keys = %v, want %v", pks, tc.want)
			}
		})
	}
	// Undated records remain searchable when no date filter is requested.
	got, err := st.Search(ctx, MessageFilter{Query: "unknown"})
	if err != nil || len(got) != 1 || got[0].SourcePK != 1 || !got[0].Timestamp.IsZero() {
		t.Fatalf("undated search = %+v, %v", got, err)
	}
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"
)

func TestBackupInitReportsLocalOnly(t *testing.T) {
	root := t.TempDir()
	var out, errOut bytes.Buffer
	args := []string{"--json", "--db", filepath.Join(root, "archive.db"), "--source", filepath.Join(root, "source"), "backup", "init", "--config", filepath.Join(root, "backup.json"), "--repo", filepath.Join(root, "repo"), "--identity", filepath.Join(root, "age.key")}
	if err := Run(context.Background(), args, &out, &errOut); err != nil {
		t.Fatalf("init: %v, %s", err, &errOut)
	}
	var result struct {
		Remote string `json:"remote"`
		Pushed *bool  `json:"pushed"`
	}
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatal(err)
	}
	if result.Remote != "" || result.Pushed == nil || *result.Pushed {
		t.Fatalf("expected local-only output, got %s", &out)
	}
}

func TestBackupHelpExplainsLocalOnly(t *testing.T) {
	var out, errOut bytes.Buffer
	if err := Run(context.Background(), []string{"backup", "--help"}, &out, &errOut); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "Backups stay local") {
		t.Fatalf("unexpected help: %s", &out)
	}
}

package backup

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	ckbackup "github.com/openclaw/crawlkit/backup"
	"github.com/openclaw/wacrawl/internal/store"
)

func TestZeroCountPublicationTransitions(t *testing.T) {
	ctx := context.Background()
	opts := zeroCountOptions(t)
	st := openFixtureStore(t, "source.db")
	runGit(t, opts.Repo, "config", "maintenance.auto", "false")
	if err := os.WriteFile(filepath.Join(opts.Repo, "notes.txt"), []byte("unrelated staged fixture"), 0o600); err != nil {
		t.Fatal(err)
	}
	runGit(t, opts.Repo, "add", "--", "notes.txt")
	staged := zeroCountGit(t, opts.Repo, "diff", "--cached", "--binary")
	var prior ckbackup.Manifest
	for _, messages := range []int{0, 1, 0} {
		t.Run(fmt.Sprintf("messages-%d-after-%d-shards", messages, len(prior.Shards)), func(t *testing.T) {
			data := zeroCountData(messages)
			if err := st.ImportSnapshot(ctx, data, "/fixture", time.Now().UTC()); err != nil {
				t.Fatal(err)
			}
			result, err := Push(ctx, st, opts)
			if err != nil || !result.Changed {
				t.Fatalf("transition push: %+v, %v", result, err)
			}
			current := zeroCountManifest(t, opts, messages, 0)
			currentPaths := map[string]bool{}
			for _, shard := range current.Shards {
				currentPaths[shard.Path] = true
			}
			for _, old := range prior.Shards {
				if !currentPaths[old.Path] {
					if _, err := scopeGit(ctx, opts.Repo, "cat-file", "-e", "HEAD:"+old.Path); err == nil {
						t.Fatalf("obsolete managed path remains committed: %s", old.Path)
					}
				}
			}
			zeroCountStable(t, st, opts, messages, 0)
			if got := zeroCountGit(t, opts.Repo, "diff", "--cached", "--binary"); got != staged {
				t.Fatal("backup changed unrelated staged content")
			}
			target := openFixtureStore(t, "restored.db")
			if err := target.ImportSnapshot(ctx, zeroCountData(1), "/fixture", time.Now().UTC()); err != nil {
				t.Fatal(err)
			}
			zeroCountPull(t, target, opts)
			got, err := target.ExportAll(ctx)
			if err != nil || len(got.Messages) != messages || len(got.Revisions) != 0 {
				t.Fatalf("restore: messages=%d revisions=%d err=%v", len(got.Messages), len(got.Revisions), err)
			}
			prior = current
		})
	}
}

func zeroCountData(messages int) store.SnapshotData {
	data := store.SnapshotData{}
	if messages != 0 {
		data.Chats = []store.Chat{{JID: "chat", Kind: "dm"}}
		data.Messages = []store.Message{{
			SourcePK: 1, ChatJID: "chat", MessageID: "one",
			Timestamp: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC), Text: "fixture",
		}}
	}
	return data
}

func zeroCountOptions(t *testing.T) Options {
	t.Helper()
	cfg := Config{Repo: filepath.Join(t.TempDir(), "repo"), Identity: filepath.Join(t.TempDir(), "age.key")}
	if err := os.Mkdir(cfg.Repo, 0o700); err != nil {
		t.Fatal(err)
	}
	recipient, err := EnsureIdentity(cfg.Identity)
	if err != nil {
		t.Fatal(err)
	}
	cfg.Recipients = []string{recipient}
	configPath := filepath.Join(t.TempDir(), "backup.json")
	if err := SaveConfig(configPath, cfg); err != nil {
		t.Fatal(err)
	}
	runGit(t, cfg.Repo, "init", "-b", "main")
	return Options{ConfigPath: configPath, Repo: cfg.Repo}
}

func zeroCountGit(t *testing.T, repo string, args ...string) string {
	t.Helper()
	data, err := scopeGit(context.Background(), repo, args...)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func zeroCountManifest(t *testing.T, opts Options, messages, revisions int) ckbackup.Manifest {
	t.Helper()
	cfg, err := ResolveOptions(opts)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err := ckbackup.ReadManifest(cfg.Repo)
	if err != nil {
		t.Fatal(err)
	}
	for key, want := range map[string]int{"messages": messages, "message_revisions": revisions, "message_sources": 0, "source_observations": 0} {
		if got, ok := manifest.Counts[key]; !ok || got != want {
			t.Fatalf("raw count %s = %d, present=%v; want %d", key, got, ok, want)
		}
		seen := 0
		for _, shard := range manifest.Shards {
			if shard.Table != key {
				continue
			}
			seen++
			if want == 0 {
				plain, err := ckbackup.DecryptShardFile(crawlkitConfig(cfg), shard)
				if err != nil || len(plain) != 0 || shard.Rows != 0 || shard.Bytes <= 0 || shard.SHA256 != ckbackup.SHA256Hex(nil) {
					t.Fatalf("invalid typed empty %s shard: %+v, %v", key, shard, err)
				}
			}
		}
		if seen != 1 {
			t.Fatalf("%s shards = %d, want one", key, seen)
		}
	}
	return manifest
}

func zeroCountPublished(t *testing.T, opts Options) map[string]string {
	t.Helper()
	cfg, err := ResolveOptions(opts)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err := ckbackup.ReadManifest(cfg.Repo)
	if err != nil {
		t.Fatal(err)
	}
	out := map[string]string{"git-head": zeroCountGit(t, cfg.Repo, "rev-parse", "HEAD")}
	paths := []string{"manifest.json"}
	for _, shard := range manifest.Shards {
		paths = append(paths, shard.Path)
	}
	for _, file := range manifest.Files {
		paths = append(paths, file.Shard)
	}
	for _, path := range paths {
		data, err := os.ReadFile(filepath.Join(cfg.Repo, filepath.FromSlash(path)))
		if err != nil {
			t.Fatal(err)
		}
		out[path] = string(data)
	}
	return out
}

func zeroCountStable(t *testing.T, st *store.Store, opts Options, messages, revisions int) {
	t.Helper()
	before := zeroCountPublished(t, opts)
	for push := 2; push <= 3; push++ {
		result, err := Push(context.Background(), st, opts)
		if err != nil || result.Changed {
			t.Fatalf("unchanged push %d: %+v, %v", push, result, err)
		}
		zeroCountManifest(t, opts, messages, revisions)
		if !reflect.DeepEqual(before, zeroCountPublished(t, opts)) {
			t.Fatalf("push %d changed manifest timestamp/bytes, ciphertext references/bytes or Git HEAD", push)
		}
	}
}

func zeroCountPull(t *testing.T, target *store.Store, opts Options) {
	t.Helper()
	if _, err := Pull(context.Background(), target, opts); err != nil {
		t.Fatal(err)
	}
}

package backup

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	ckbackup "github.com/openclaw/crawlkit/backup"
)

func TestAuditBackupAllowsSiblingRepository(t *testing.T) {
	ctx := context.Background()
	st := openFixtureStore(t, "archive.db")
	parent := filepath.Dir(st.Path())
	remote := filepath.Join(t.TempDir(), "remote.git")
	runGit(t, t.TempDir(), "init", "--bare", remote)
	opts := Options{
		ArchivePath: st.Path(), Repo: filepath.Join(parent, "backup"), Remote: remote,
		Identity: filepath.Join(parent, "age.key"), ConfigPath: filepath.Join(parent, "backup.json"),
	}
	if _, _, err := Init(ctx, opts); err != nil {
		t.Fatal(err)
	}
	if _, err := Push(ctx, st, opts); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{st.Path(), st.Path() + "-wal", st.Path() + "-shm", st.Path() + "-journal", filepath.Join(parent, "media")} {
		bad := opts
		bad.Repo = name
		if err := ValidateWriteOptions(bad); err == nil {
			t.Fatalf("accepted protected archive path %q", name)
		}
	}
}

func TestAuditBackupRejectsSymlinkParentTraversalBeforeWrites(t *testing.T) {
	source := t.TempDir()
	if err := os.Mkdir(filepath.Join(source, "nested"), 0o700); err != nil {
		t.Fatal(err)
	}
	alias := filepath.Join(t.TempDir(), "alias")
	if err := os.Symlink(filepath.Join(source, "nested"), alias); err != nil {
		t.Fatal(err)
	}
	remote := filepath.Join(t.TempDir(), "remote.git")
	runGit(t, t.TempDir(), "init", "--bare", remote)
	opts := Options{
		SourcePath: source, Repo: alias + string(filepath.Separator) + "../backup", Remote: remote,
		Identity: filepath.Join(t.TempDir(), "age.key"), ConfigPath: filepath.Join(t.TempDir(), "backup.json"),
	}
	if _, _, err := Init(context.Background(), opts); err == nil {
		t.Fatal("accepted an OS path resolving inside the selected source")
	}
	for _, name := range []string{filepath.Join(source, "backup"), opts.ConfigPath, opts.Identity} {
		if _, err := os.Lstat(name); !os.IsNotExist(err) {
			t.Fatalf("rejected layout wrote %q: %v", name, err)
		}
	}
}

func TestAuditBackupRejectsFileSourceHardlink(t *testing.T) {
	source := filepath.Join(t.TempDir(), "source.db")
	sentinel := []byte("synthetic source sentinel")
	if err := os.WriteFile(source, sentinel, 0o600); err != nil {
		t.Fatal(err)
	}
	config := filepath.Join(t.TempDir(), "backup.json")
	if err := os.Link(source, config); err != nil {
		t.Fatal(err)
	}
	cfg := Config{Repo: filepath.Join(t.TempDir(), "repo"), Identity: filepath.Join(t.TempDir(), "age.key")}
	if err := validateWriteLayout(cfg, Options{SourcePath: source, ConfigPath: config}); err == nil {
		t.Fatal("accepted a config hardlink to the selected source file")
	}
	got, err := os.ReadFile(source) // #nosec G304 -- fixed source.db sentinel created in t.TempDir; verifies hardlink refusal preserved its bytes.
	if err != nil || string(got) != string(sentinel) {
		t.Fatalf("source changed: %q %v", got, err)
	}
}

func TestAuditInitPreservesIdentityOnCaseInsensitiveFilesystem(t *testing.T) {
	parent := t.TempDir()
	if err := os.WriteFile(filepath.Join(parent, "probe"), nil, 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(parent, "PROBE")); os.IsNotExist(err) {
		t.Skip("requires a case-insensitive filesystem")
	}
	opts := Options{Repo: filepath.Join(t.TempDir(), "repo"), Identity: filepath.Join(parent, "age.key"), ConfigPath: filepath.Join(parent, "AGE.KEY")}
	if _, _, err := Init(context.Background(), opts); err == nil {
		t.Fatal("accepted case-equivalent config and identity")
	}
	if _, err := RecipientFromIdentity(opts.Identity); err != nil {
		t.Fatalf("generated identity was overwritten: %v", err)
	}
	if _, err := os.Stat(opts.Repo); !os.IsNotExist(err) {
		t.Fatal("initialized publication repository after alias detection")
	}
}

func TestAuditInitChecksConfigCreatedCaseAlias(t *testing.T) {
